from collections.abc import Iterable

def validate_orders(rows: Iterable[dict[str, object]]) -> list[dict[str, object]]:
    cleaned: list[dict[str, object]] = []
    seen_ids: set[str] = set()
    for row in rows:
        order_id = row.get('order_id')
        amount = row.get('amount')
        if not isinstance(order_id, str) or not order_id:
            raise ValueError('order_id must be a non-empty string')
        if order_id in seen_ids:
            raise ValueError(f'duplicate order_id: {order_id}')
        if not isinstance(amount, (int, float)) or isinstance(amount, bool) or amount < 0:
            raise ValueError(f'invalid amount for {order_id}')
        seen_ids.add(order_id)
        cleaned.append({'order_id': order_id, 'amount': float(amount)})
    return cleaned

